        logger.warn("Symbol '" + SecuritySymbols.REMEMBERME_CIPHERKERY + "' is not set, using '"
                + SymbolConstants.HMAC_PASSPHRASE
                + "' as the cipher. Beware that changing the value will invalidate rememberMe cookies.");
        cipherKey = hmacPassphrase;
    }

    // Ensure the cipher key is of a suitable length
    rememberMeManager.setCipherKey(ensureKeyLength(cipherKey.getBytes("UTF-8")));
    return rememberMeManager;
}

private static byte[] ensureKeyLength(byte[] key) {
    // Ensure the key is of valid length for the cipher
    // For AES, typical lengths are 16, 24, or 32 bytes
    final int AES_KEY_LENGTH = 16;
    if (key.length < AES_KEY_LENGTH) {
        byte[] paddedKey = new byte[AES_KEY_LENGTH];
        System.arraycopy(key, 0, paddedKey, 0, key.length);
        return paddedKey;
    }
    return key;
}

private static byte[] generateRandomKey() {
    // Generate a key of length appropriate for the cipher
    byte[] key = new byte[16]; // 16 bytes = 128 bits for AES
    new java.security.SecureRandom().nextBytes(key);
    return key;
}

